from dataclasses import dataclass


@dataclass
class Event:
    name: str
    value: str
    correlation_id: str | None = None

def process(event: Event) -> dict:
    record = {"name": event.name, "value": event.value}
    if event.correlation_id is not None:
        record["correlation_id"] = event.correlation_id
    return record

def as_text(record: dict) -> str:
    text = f"{record['name']}={record['value']}"
    correlation_id = record.get("correlation_id")
    if correlation_id is not None:
        text += f" correlation_id={correlation_id}"
    return text

